import * as T from './vendor/three.module.min.js';
const B=new T.BoxGeometry(1,1,1),S=new T.SphereGeometry(1,14,10),C=new T.CylinderGeometry(1,1,1,12),cache=new Map();
const material=c=>{if(!cache.has(c))cache.set(c,new T.MeshStandardMaterial({color:c,roughness:.82}));return cache.get(c);};
function part(g,geometry,color,x,y,z,sx,sy,sz){const m=new T.Mesh(geometry,typeof color==='string'?material(color):color);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=m.receiveShadow=true;g.add(m);return m;}
