// Consolidate stationary details by material: hundreds of tiles/frames use a handful of draws.
export function batch(group){group.updateMatrixWorld(true);const batches=new Map(),inverse=group.matrixWorld.clone().invert();group.traverse(o=>{if(!o.isMesh)return;const m=o.material;if(!batches.has(m))batches.set(m,[]);batches.get(m).push(o);});const out=[];
 for(const [m,items]of batches){const positions=[],normals=[],uv=[],indices=[];let offset=0;for(const o of items){const g=o.geometry,transform=inverse.clone().multiply(o.matrixWorld),normalMatrix=new T.Matrix3().getNormalMatrix(transform),p=g.attributes.position,n=g.attributes.normal,t=g.attributes.uv,v=new T.Vector3();for(let i=0;i<p.count;i++){v.fromBufferAttribute(p,i).applyMatrix4(transform);positions.push(v.x,v.y,v.z);if(n)v.fromBufferAttribute(n,i).applyMatrix3(normalMatrix).normalize();else v.set(0,1,0);normals.push(v.x,v.y,v.z);uv.push(t?t.getX(i):0,t?t.getY(i):0);}const ix=g.index?.array||Array.from({length:p.count},(_,i)=>i);for(const i of ix)indices.push(i+offset);offset+=p.count;}
  const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(positions,3));g.setAttribute('normal',new T.Float32BufferAttribute(normals,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(indices);g.computeBoundingSphere();const mesh=new T.Mesh(g,m);mesh.castShadow=mesh.receiveShadow=true;out.push(mesh);
 }group.clear();out.forEach(o=>group.add(o));return group;
}
function planter(g,x,y,z,large=false){const r=large?.34:.17;cyl(g,x,y+r*.8,z,r,r*1.6,'#b78361');cyl(g,x,y+r*1.55,z,r*1.08,.09,'#dbad82');for(let i=0;i<6;i++){const a=i*2.4;const leaf=ball(g,x+Math.sin(a)*r*.7,y+r*2.2+(i%2)*r*.5,z+Math.cos(a)*r*.7,r*.6,r*1.15,r*.35,i%2?'#81984f':'#557c50');leaf.rotation.z=Math.sin(a)*.5;}}
function tree(g,x,z,seed){const trunk=cyl(g,x,1.8,z,.14,3.6,'#8a7553');trunk.rotation.z=.025;for(let i=0;i<3;i++){const a=i*2.1,b=cyl(g,x+Math.sin(a)*.25,2.7,z+Math.cos(a)*.25,.065,1.3,'#8a7553');b.rotation.z=Math.sin(a)*.6;}for(let i=0;i<7;i++){const a=i*2.4+seed;ball(g,x+Math.sin(a)*.9,3.5+(i%3)*.36,z+Math.cos(a)*.8,1.05,.85,1.04,['#719263','#92a86d','#809c5f'][i%3]);}cyl(g,x,.13,z,.75,.22,'#b3b397');for(let i=0;i<5;i++)ball(g,x+Math.sin(i*2.4)*.55,.27,z+Math.cos(i*2.4)*.55,.25,.16,.25,'#64864d');}
