function bicycle(g,x,z,rotation){const q=new T.Group();q.position.set(x,.1,z);q.rotation.y=rotation;g.add(q);for(const x of [-.56,.56]){const w=new T.Mesh(new T.TorusGeometry(.40,.035,8,24),material('#405649'));w.position.set(x,.43,0);q.add(w);for(let k=0;k<8;k++){const s=box(q,x,.43,0,.014,.76,.014,'#b9bca6');s.rotation.z=k/8*Math.PI;}}
 const rod=(a,b,color,r=.035)=>{const A=new T.Vector3(...a),D=new T.Vector3(...b).sub(A),m=cyl(q,0,0,0,r,D.length(),color);m.position.copy(A.addScaledVector(D,.5));m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),D.normalize());};
 for(const [a,b]of [[[-.56,.43,0],[0,.45,0]],[[0,.45,0],[-.17,1,0]],[[-.17,1,0],[-.56,.43,0]],[[-.17,1,0],[.39,.94,0]],[[.39,.94,0],[0,.45,0]],[[.39,.94,0],[.56,.43,0]]])rod(a,b,'#d89b62');rod([.39,.94,0],[.34,1.22,0],'#405649');box(q,.34,1.22,0,.08,.04,.44,'#405649');box(q,-.18,1.04,0,.28,.07,.18,'#5c6552');box(q,.66,.96,0,.35,.35,.34,'#b9aa83');}
export function shop(g,index,side){const b=new T.Group();b.position.set(side*10,0,0);b.rotation.y=-side*Math.PI/2;g.add(b);const palette=['#d5bfa0','#d9a88a','#a5b5a0','#e0ceb0','#b7b8a0','#c7ab98'],paint=palette[index%palette.length],h=5.0+index%3*.65;box(b,0,h/2,0,6.3,h,4.5,paint);box(b,0,.30,0,6.5,.60,4.6,'#a19e82');box(b,0,3.32,2.29,6.4,.14,.16,'#f1e0b8');box(b,0,h-.2,2.29,6.5,.18,.20,'#f1e0b8');
 // Pitched tile roof, repeated ridges and a chimney.
 const roofShape=new T.Shape();roofShape.moveTo(-3.5,0);roofShape.lineTo(0,1.35);roofShape.lineTo(3.5,0);roofShape.lineTo(-3.5,0);const r=new T.Mesh(new T.ExtrudeGeometry(roofShape,{depth:5.0,bevelEnabled:false}),material(index%2?'#8c7664':'#6f8879'));r.position.set(0,h,-2.5);b.add(r);for(const s of [-1,1])for(let k=0;k<11;k++){const tile=box(b,s*1.75,h+.72,-2.4+k*.48,3.76,.06,.045,index%2?'#a18a73':'#8ba08c');tile.rotation.z=-s*.368;}box(b,1.8,h+.65,-.7,.58,1.4,.58,'#aa9380');box(b,1.8,h+1.36,-.7,.72,.13,.72,'#d3bf9e');
 const door=-1.85;box(b,door,1.55,2.31,1.3,2.55,.10,'#476f64');box(b,door,1.7,2.38,.92,1.8,.025,'#91b5ae');box(b,door,1.16,2.42,.97,.08,.04,'#e4d7b0');ball(b,door+.4,1.35,2.46,.04,.04,.035,'#d1b367');box(b,door,.13,2.5,1.5,.12,.55,'#c4b99c');
 for(const x of [.1,1.8]){box(b,x,1.75,2.31,1.48,2.0,.12,'#40635c');box(b,x,1.75,2.4,1.28,1.78,.025,'#85aaa6');for(const dx of [-.72,.72])box(b,x+dx,1.75,2.46,.07,2.0,.08,'#f0e3c5');box(b,x,1.72,2.46,1.45,.065,.07,'#e3d4ad');box(b,x,.75,2.45,1.6,.13,.22,'#ddc8a3');for(let j=0;j<3;j++)box(b,x-.4+j*.4,1.15,2.43,.22,.35+(j%2)*.15,.05,['#deb06d','#ecd2a1','#bf9676'][j]);}
 for(const x of [-1.7,1.7]){box(b,x,h-1.1,2.31,1.4,1.35,.10,'#47645f');box(b,x,h-1.1,2.4,1.22,1.17,.035,'#a7c7bd');box(b,x,h-1.1,2.44,1.3,.07,.05,'#eee0bb');box(b,x,h-1.1,2.45,.07,1.3,.05,'#eee0bb');box(b,x,h-1.83,2.43,1.65,.13,.30,'#d6c3a2');for(const s of [-1,1])box(b,x+s*.87,h-1.1,2.36,.3,1.42,.13,index%2?'#768d70':'#b48667');planter(b,x,h-1.77,2.56);}
 const names=['奶蛙便利店','好心情花店','慢慢咖啡','放学面包屋','一口奶茶','快乐邮局'];text(b,names[index%6],.1,3.0,2.49,4.9,.66,index%2?'#d8aa6f':'#557e68',index%2?'#4d624d':'#fff1cc');
 const awning=new T.Group();awning.position.set(0,2.65,2.8);awning.rotation.x=.20;b.add(awning);for(let j=0;j<10;j++){box(awning,-2.88+j*.64,0,0,.64,.09,1.0,j%2?'#eee1bc':index%2?'#c58c65':'#709886');ball(awning,-2.88+j*.64,-.11,.49,.32,.17,.05,j%2?'#eee1bc':index%2?'#c58c65':'#709886');}
 planter(b,-2.75,.14,2.85,true);planter(b,2.65,.14,2.85,true);
 // Bricks, shutters, and side-window details visible from the chase camera.
 for(let k=0;k<7;k++)for(const s of [-1,1])box(b,s*3.17,.6+k*.52,2.05,.08,.22,.38,'#c4af92');for(const x of [-3.17,3.17])for(const z of [-1.15,.8]){box(b,x,2.0,z,.07,1.5,1.0,'#6b8b82');box(b,x*1.003,2.0,z,.08,.06,1.02,'#e8dbb9');}
 const board=new T.Group();board.position.set(-.7,.12,3.4);board.rotation.y=.12;b.add(board);box(board,0,.62,0,.78,1.2,.09,'#ad8c64');text(board,index%2?'今日快乐':'来杯奶茶',0,.65,.054,.65,.87,'#405e51','#efe3bc');for(const x of [-.35,.35])box(board,x,.3,-.2,.055,.6,.07,'#9b815d').rotation.x=-.2;
}
export function park(g,side,seed){const x=side*10;box(g,x,.1,0,6,.28,13,'#a8b77e');const pond=cyl(g,x,.25,-1,2.2,.12,'#70aaa1');pond.scale.z*=1.45;for(let k=0;k<7;k++){const a=k*2.4;const leaf=cyl(g,x+Math.sin(a)*1.7,.33,-1+Math.cos(a)*2.4,.40,.018,'#7a9b56');leaf.scale.z*=.7;if(k%2===0)ball(g,leaf.position.x,.39,leaf.position.z,.12,.08,.12,'#eac7bb');}tree(g,x+side*1.5,5,seed);tree(g,x+side*1.8,-6,seed+2);bench(g,side*6.6,2,-side*Math.PI/2);for(let k=0;k<12;k++){const z=-6+k;const xx=side*(7.6+Math.sin(k*3.3)*.3);cyl(g,xx,.38,z,.025,.5,'#6e8951');for(let j=0;j<4;j++)ball(g,xx+Math.sin(j*Math.PI/2)*.09,.67,z+Math.cos(j*Math.PI/2)*.09,.09,.045,.09,k%2?'#e6ba7e':'#cf9dab');}}
export function createTown(parent){const root=new T.Group();parent.add(root);const chunks=[],parks=[],shops=[];const length=18,count=10;
 for(let i=0;i<count;i++){const g=new T.Group();root.add(g);const city=new T.Group(),garden=new T.Group();g.add(city,garden);for(const side of [-1,1]){if((i+side+1)%4===0)park(city,side,i);else shop(city,i+(side===1?1:0),side);park(garden,side,i);tree(g,side*6.85,-6.3,i);for(let k=0;k<12;k++)box(g,side*5.57,.17,-8.7+k*1.5,.22,.32,1.42,k%2?'#d8d5b8':'#bdbfa4');
  cyl(g,side*6.2,2.5,5.3,.065,5,'#4b6a5d');cyl(g,side*6.2,.45,5.3,.14,.75,'#4b6a5d');box(g,side*6.2,5.0,5.3,.64,.08,.57,'#4b6a5d');box(g,side*6.2,4.77,5.3,.36,.4,.36,'#eee0a5');for(const xx of [-.20,.20])for(const zz of [-.2,.2])box(g,side*6.2+xx,4.77,5.3+zz,.035,.5,.035,'#4b6a5d');
  if(i%2===0)bicycle(city,side*6.7,3.7,side*Math.PI/2);else bench(city,side*6.55,4,-side*Math.PI/2);
  cyl(g,side*6.5,.55,7,.22,.9,'#6b8771');cyl(g,side*6.5,1.01,7,.25,.10,'#526d5a');
 }
 if(i%3===0){for(let k=-3;k<=3;k++)box(g,k*1.45,.052,8,1,.015,2,'#e3ddbb');cyl(g,4.1,.055,3,.55,.02,'#596b5e');}
 batch(city);batch(garden);chunks.push(g);shops.push(city);parks.push(garden);garden.visible=false;
 // Batch shared street furniture separately so route visibility remains independent.
 const furniture=new T.Group();for(const child of [...g.children])if(child!==city&&child!==garden)furniture.add(child);g.add(batch(furniture));
 }
 const far=new T.Group();root.add(far);for(let i=0;i<10;i++)ball(far,(i-5)*20,3,-125-(i%3)*15,22,12+i%4*4,18,i%2?'#9cbb9d':'#b4c7a7');
 const tower=new T.Group();tower.position.set(17,0,-105);far.add(tower);box(tower,0,6,0,5,12,5,'#d4c7a5');box(tower,0,12,0,5.7,.6,5.7,'#6d8c78');const clock=cyl(tower,0,9.7,2.56,1.5,.08,'#eee2b7');clock.rotation.x=Math.PI/2;box(tower,0,10.05,2.63,.09,.8,.05,'#586d58');box(tower,.35,9.7,2.63,.8,.09,.05,'#586d58');batch(far);
 return {root,update(distance,time,route){for(let i=0;i<count;i++){chunks[i].position.z=18-((i*length+count*length-distance%(count*length))%(count*length));parks[i].visible=route==='garden';shops[i].visible=route!=='garden';}far.position.x=Math.sin(distance*.001)*2;}};
}
export function groundTexture(kind){const c=document.createElement('canvas');c.width=c.height=256;const x=c.getContext('2d');let seed=42;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};x.fillStyle=kind==='road'?'#7b8c83':'#c9c6aa';x.fillRect(0,0,256,256);for(let i=0;i<7000;i++){const q=rand();x.fillStyle=q>.5?'#ffffff0a':'#182c2109';x.fillRect(rand()*256,rand()*256,1+rand()*2,1+rand()*2);}if(kind!=='road'){x.strokeStyle='#7f8e7144';x.lineWidth=2;for(let r=0;r<8;r++){for(let k=0;k<6;k++){x.strokeRect(k*64-(r%2)*32,r*32,64,32);}}}const t=new T.CanvasTexture(c);t.wrapS=t.wrapT=T.RepeatWrapping;t.colorSpace=T.SRGBColorSpace;t.repeat.set(kind==='road'?3:2,kind==='road'?45:38);return t;}
